mapper.select:
		SELECT
			am.*,
			ar.alert_name,
			ar.expr,
			ar.operator,
			ar.threshold,
			ar.unit
		FROM
			alert_message am
		LEFT JOIN alert_rule ar ON am.rule_id = ar.id


				ar.alert_name like concat('%', #{params.alertName}, '%')



				AND am.severity=#{params.severity}



				AND am.summary like concat('%', #{params.summary}, '%')



				AND am.description like concat('%', #{params.description}, '%')



				AND am.id=#{params.id}


                AND am.state=#{params.state}


				AND am.start_at >= #{params.startAt}


				AND am.start_at <= #{params.endAt}



				AND am.rule_id = #{params.ruleId}



				AND am.project_id = #{params.projectId}



				AND am.module_id = #{params.moduleId}



				AND am.endpoint_id = #{params.endpointId}



				AND am.asset_id = #{params.assetId}



				AND am.dc_id = #{params.dcId}



				AND am.labels = #{params.labels}




		/* 如果排序字段为null , 使用默认排序 */

			ORDER BY am.state , am.start_at DESC

mapper.update:
 UPDATE alert_message am SET am.state = 2, am.end_at = #{nowDate}
 WHERE am.hash_key IN

	#{hashKey}

AND state = 1

mapper.select:
		SELECT am.id,am.labels,am.endpoint_id endpoint,am.severity,am.summary,am.description,am.start_at startAt,am.end_at endAt,am.state state,
		ar.alert_name alertName,a. host asset,p.name project,i.name datacenter,m.name module
        FROM alert_message am
        LEFT JOIN alert_rule ar ON ar.id = am.rule_id LEFT JOIN asset a ON a.id = am.asset_id
        LEFT JOIN project p ON p.id = am.project_id LEFT JOIN idc i ON i.id = am.dc_id
        LEFT JOIN module m ON m.id = am.module_id
        WHERE 1=1

			AND am.id = #{params.id}


			AND am.rule_id= #{params.ruleId}


			AND am.dc_id= #{params.dcId}


			AND am.project_id= #{params.projectId}


			AND am.module_id= #{params.moduleId}


			AND am.asset_id= #{params.assetId}


			AND am.endpoint_id= #{params.endpointId}


			AND am.severity= #{params.severity}


			AND am.summary  like concat('%',#{params.summary},'%')


			AND am.description like concat('%',#{params.description},'%')


			and am.labels like concat('%',#{params.labels},'%')


			AND am.state=#{params.state}


			AND am.start_at = #{params.startAt}


			AND am.end_at = #{params.endAt}


			and ar.id in

				#{ruleId}



			ORDER BY am.state , am.start_at DESC

		LIMIT #{params.pageNo},#{params.pageSize}

mapper.update:
update alert_message am set remark = #{params.remark} , state = #{params.state}

	, end_at = #{params.endAt}

where id in

	#{id}
